{"hypotheses":[
  {"statement":"Beverage revenue is high primarily because a small number of products dominate drink sales, i.e. product concentration rather than broad-based demand.","priorConfidence":0.55,"target":"beverage_revenue_by_product","action":"breakdown","expectation":"A small subset of product_name values (e.g. top 2-3) account for a disproportionate share (>60%) of order_item.drink_revenue; if revenue is spread evenly across many products, this is refuted."},
  {"statement":"Beverage revenue is high because one customer_type segment (e.g. a specific customer type) drives disproportionately more drink purchases than others.","priorConfidence":0.5,"target":"top_beverage_customers","action":"breakdown","expectation":"drink_revenue broken down by customer_type shows one segment contributing a majority share, well above its share of total customers; even distribution across customer_type refutes this."},
  {"statement":"High beverage revenue reflects sustained month-over-month growth in drink sales rather than a one-time spike.","priorConfidence":0.4,"target":"order_item.revenue_growth_mom","action":"compare_time","expectation":"order_item.revenue_growth_mom for drink revenue shows consistent positive growth across multiple recent months; a single-month spike followed by flat/negative growth refutes this."},
  {"statement":"Beverage revenue is high due to a high volume of drink orders rather than high revenue per order.","priorConfidence":0.45,"target":"orders.drink_orders","action":"compare_time","expectation":"orders.drink_orders count trends upward in line with order_item.drink_revenue growth, and order_item.median_revenue per drink order stays flat; if median revenue per order is rising while order count is flat, this is refuted."},
  {"statement":"Beverage revenue is high because a small set of top customers make outsized repeat purchases, i.e. customer concentration rather than broad customer base growth.","priorConfidence":0.4,"target":"top_beverage_customers","action":"breakdown","expectation":"top_beverage_customers shows a small number of customer_name entries accounting for a large share (>50%) of drink_revenue; if spend is evenly distributed across many customers, this is refuted."}
]}
